from .money import MAX_CENTS, cents_to_decimal, format_amount, parse_cents


def make_invoice(amounts):
    if not isinstance(amounts, (list, tuple)):
        raise ValueError("amounts must be a list")
    total = 0
    for item in amounts:
        total += parse_cents(item)
    if total > MAX_CENTS:
        raise ValueError("invoice total must be at most 1000000.00")
    return {"total": format_amount(cents_to_decimal(total)), "count": len(amounts)}
